<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('search.use');$pdo=staff_db();$q=trim($_GET['q']??'');$like='%'.$q.'%';$results=[];if($q!==''){$sets=[['customer','Customers','SELECT id,customer_code code,name title,phone sub FROM customers WHERE name LIKE ? OR customer_code LIKE ? OR phone LIKE ? LIMIT 10','staff/pages/customer-view.php?id='],['project','Projects','SELECT id,project_code code,name title,status sub FROM projects WHERE name LIKE ? OR project_code LIKE ? LIMIT 10','staff/pages/project-view.php?id='],['quote','Quotations','SELECT id,quotation_no code,quotation_no title,status sub FROM quotations WHERE quotation_no LIKE ? OR status LIKE ? OR CAST(total_amount AS CHAR) LIKE ? LIMIT 10','staff/pages/quotation-centre.php?q='],['supplier','Suppliers','SELECT id,supplier_code code,company_name title,phone sub FROM suppliers WHERE company_name LIKE ? OR supplier_code LIKE ? OR phone LIKE ? LIMIT 10','staff/pages/suppliers.php?q=']];foreach($sets as [$type,$label,$sql,$url]){try{foreach(db_rows($pdo,$sql,[$like,$like,$like]) as $r)$results[]=['type'=>$label,'url'=>$url.$r['id']]+$r;}catch(Throwable $e){}}}$pageTitle='Global Search';require __DIR__.'/../../includes/staff/header.php';module_head('Find anything','Global Search','Search customers, projects, quotations and suppliers from one place.');?><section class="staff-panel"><form method="get" class="search-row"><label style="flex:1">Search<input autofocus name="q" value="<?=h($q)?>" placeholder="Customer, project code, phone, quotation, supplier..."></label><button class="btn primary">Search</button></form></section><section class="staff-panel"><h2><?=count($results)?> results</h2><?php foreach($results as $r):?><a class="link-card" href="<?=h(ideare_root_url($r['url']))?>"><small><?=h($r['type'])?></small><b><?=h($r['title'])?></b><div><?=h(($r['code']??'').' · '.($r['sub']??''))?></div></a><?php endforeach?></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>